import json
import os
import time
from app.config import CACHE_PATH, CACHE_TTL

def get_or_load(key, loader, now=None):
    """Get cached value or load and cache it."""
    if now is None:
        now = time.time()

    # Load existing cache file
    cache = {}
    if os.path.exists(CACHE_PATH):
        try:
            with open(CACHE_PATH, 'r') as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            cache = {}

    # Check if key exists and is not expired
    if key in cache:
        entry = cache[key]
        age = now - entry.get('stored_at', 0)
        if age < CACHE_TTL:
            return entry.get('value')

    # Load new value and cache it
    value = loader()
    cache[key] = {'stored_at': now, 'value': value}

    # Ensure directory exists and write cache
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, 'w') as f:
        json.dump(cache, f)

    return value"}]}

