import json

def audit_log(logger, request, response):
    """Log complete request and response details as JSON."""
    # Get request body
    request_body = ''
    if request.method in ('POST', 'PUT', 'PATCH'):
        try:
            request_body = request.get_data(as_text=True)
        except Exception:
            request_body = ''

    # Get response body
    response_body = ''
    try:
        response_body = response.get_data(as_text=True)
    except Exception:
        response_body = ''

    # Build log entry
    entry = {
        'method': request.method,
        'path': request.path,
        'request_body': request_body,
        'response_body': response_body
    }

    logger.info(json.dumps(entry))"}]}

